def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    threat_bids = []
    rich_threat = 0.0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > rich_threat:
                rich_threat = opp.get('budget', 0)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('budget', 0) > DAILY_SALARY * 4 or opp.get('hp', 0) >= 6:
                    threat_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else highest_prev

    tight_supply = supply <= 17
    very_tight = supply <= 15.5
    danger = hp <= 3 or no_water_days >= 2
    caution = hp <= 5 or no_water_days >= 1

    if danger:
        bid = max(DAILY_SALARY * 0.88, highest_threat + 2.0)
    elif very_tight:
        bid = max(DAILY_SALARY * 0.72, highest_threat + 1.5)
    elif tight_supply:
        bid = max(DAILY_SALARY * 0.6, highest_threat * 0.92 + 1.0)
    elif caution:
        bid = max(DAILY_SALARY * 0.48, highest_threat * 0.75)
    else:
        bid = max(DAILY_SALARY * 0.34, highest_threat * 0.55)

    if highest_prev >= DAILY_SALARY * 0.9 and not danger and hp >= 6:
        bid = min(bid, DAILY_SALARY * 0.42)

    if day >= 8 and hp >= 6 and budget < rich_threat:
        bid = min(bid, DAILY_SALARY * 0.45)

    if budget <= DAILY_SALARY * 0.8:
        if danger:
            bid = max(min(budget, DAILY_SALARY * 0.85), min(budget, highest_threat + 1.0))
        else:
            bid = min(bid, budget)

    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents are alive, conserve water
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.35)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    # Estimate what supply can support: number of full water quanta
    # (Not directly used for indexing; just for scaling)
    supply_quanta = max(1.0, float(supply) / float(WATER_REQ))

    # Determine if Cindy is likely to be the high-pressure bidder
    cindy = opponents_status.get('Cindy', None)
    cindy_alive = bool(cindy and cindy.get('alive', False))
    cindy_prev_bid = None
    if cindy:
        prev = cindy.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            cindy_prev_bid = float(prev['bid'])

    # Determine opponent pressure level from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Core strategy:
    # - If Cindy was aggressive yesterday, match slightly above her to secure water.
    # - Otherwise, bid based on our HP: low HP => bid high; high HP => bid moderate.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Budget safety: never bid more than budget
    def clamp_bid(x):
        if x < 0:
            return 0.0
        return min(my_budget, x)

    # Aggressive match if Cindy was high
    if cindy_alive and cindy_prev_bid is not None:
        # Cindy averaged ~63.78 yesterday; use thresholds around that.
        if cindy_prev_bid >= DAILY_SALARY * 0.55:
            # Bid just above her yesterday bid, but scaled by supply pressure.
            # Supply 15 => less water; bid a bit more. Supply 25 => bid slightly less.
            supply_bias = 1.08 if supply <= (MIN_SUPPLY + 0.5) else 0.98
            target = (cindy_prev_bid + 2.0) * supply_bias
            # If our HP is very low, increase urgency
            if my_hp <= 2.0:
                target *= 1.25
            return clamp_bid(target)

    # Otherwise react to overall highest bid
    if highest_prev_bid >= DAILY_SALARY * 0.7:
        # Very high contention: bid to avoid being starved
        if my_hp <= 2.0:
            return clamp_bid(DAILY_SALARY * 0.95)
        return clamp_bid(max(highest_prev_bid + 1.5, DAILY_SALARY * 0.65))

    if highest_prev_bid >= DAILY_SALARY * 0.4:
        # Moderate contention
        if my_hp <= 3.0:
            return clamp_bid(max(highest_prev_bid + 1.0, DAILY_SALARY * 0.6))
        return clamp_bid(max(second_prev_bid + 2.0, DAILY_SALARY * 0.5))

    # Low contention: bid based on HP and remaining budget
    if my_hp <= 2.0:
        return clamp_bid(DAILY_SALARY * 0.85)
    if my_hp <= 4.0:
        return clamp_bid(DAILY_SALARY * 0.65)

    # If we have decent HP, conserve while still competing for water
    # Scale slightly with supply quanta (more supply => can afford lower bid)
    conserve_factor = 0.55 if supply_quanta >= (float(MAX_SUPPLY) / float(WATER_REQ)) else 0.6
    return clamp_bid(DAILY_SALARY * conserve_factor)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    bid_amount = DAILY_SALARY * 0.6 # Default moderate bid

    if not alive_opponents:
        bid_amount = DAILY_SALARY * 0.1 # Bid low to save money if no competition
        return max(0.0, min(my_status['budget'], bid_amount))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        HIGH_COMPETITION_THRESHOLD = DAILY_SALARY * 0.85 # 127.5

        if highest_prev_bid >= HIGH_COMPETITION_THRESHOLD:
            if my_status['hp'] > 5: # Relatively safe HP
                bid_amount = DAILY_SALARY * 0.4 # Risk a lower bid to save budget
            else: # Low HP, need water desperately
                bid_amount = DAILY_SALARY * 0.95 # Bid very high
        else:
            bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid + 5.0)
    else:
        if my_status['hp'] <= 3: # Low HP, need water
            bid_amount = DAILY_SALARY * 0.9
        else: # Normal HP
            bid_amount = DAILY_SALARY * 0.6

    day_factor = 1 + (day_context['day'] / EPISODE_DAYS) * 0.15
    bid_amount *= day_factor

    final_bid = min(my_status['budget'], bid_amount)

    return max(0.0, final_bid)
